def squash(s: str) -> str:
    def esc(c: str) -> str:
        if c == "\\" or "0" <= c <= "9":
            return "\\" + c
        return c

    n = len(s)
    if n == 0:
        return ""
    parts = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run = j - i
        if run >= 3:
            parts.append(str(run))
            parts.append(esc(c))
        else:
            e = esc(c)
            parts.append(e if run == 1 else e + e)
        i = j
    return "".join(parts)
